#!/usr/bin/env bash
# Rebuilds the synthetic parity fixture database from scratch:
#
#   parity/fixture/rebuild.sh
#
# Destroys any existing fixture container, starts a fresh PostgreSQL on
# 127.0.0.1:55432 with an empty tmpfs data directory, loads sql/01_schema.sql
# and sql/02_seed.sql, and returns once the seed is queryable.
#
# The seed is generated by `go run ./parity/fixture/gen`; regenerate it only
# when the scenarios change (TestGeneratedFilesUpToDate guards drift).
set -euo pipefail
cd "$(dirname "$0")"
docker compose -f compose.yaml down --remove-orphans >/dev/null 2>&1 || true
docker compose -f compose.yaml up -d --force-recreate --renew-anon-volumes --wait
echo "parity fixture ready: postgres://postgres@127.0.0.1:55432/parity_fixture?sslmode=disable"
